package dev.smokekitchen.cooking;

import dev.smokekitchen.content.ContentCatalog;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class StapleCookingTest {
    private DishRecipe recipe(String id){if(ContentCatalog.DISHES.isEmpty())ContentCatalog.load();return ContentCatalog.DISHES.stream().filter(r->r.id().equals(id)).findFirst().orElseThrow();}
    private CookingBatch batch(CookingBatch.Method method,double water){var b=new CookingBatch();b.method=method;b.addWater(water);b.temperature=100;return b;}
    private void ready(CookingBatch b){b.ingredients.forEach(p->p.cooked=1);}
    @Test void riceRequiresMeasuredWaterAndCoveredLowHeat(){var r=recipe("cooked_rice");var b=batch(CookingBatch.Method.BOIL,2);b.add("rice",CookingBatch.Cut.WHOLE,1,true,false);ready(b);assertEquals("low_heat",r.problem(b).orElseThrow().key());b.ingredients.getFirst().lowHeatSeconds=10;assertTrue(r.matches(b));b.ingredients.getFirst().waterOnAdd=6;assertEquals("water_ratio",r.problem(b).orElseThrow().key());}
    @Test void actualLowHeatEvidenceDoesNotAccumulateOnHighHeatOrUncovered(){var b=batch(CookingBatch.Method.BOIL,2);b.add("rice",CookingBatch.Cut.WHOLE,1,true,false);for(int i=0;i<30;i++)b.tick(2,true);assertEquals(0,b.ingredients.getFirst().lowHeatSeconds);for(int i=0;i<15;i++)b.tick(1,false);assertEquals(0,b.ingredients.getFirst().lowHeatSeconds);for(int i=0;i<15;i++)b.tick(1,true);assertTrue(b.ingredients.getFirst().lowHeatSeconds>=10);}
    @Test void porridgeNeedsMoreWaterSofteningAndStirring(){var r=recipe("rice_porridge");var b=batch(CookingBatch.Method.STEW,6);b.add("rice",CookingBatch.Cut.WHOLE,1,true,false);ready(b);assertEquals("soften",r.problem(b).orElseThrow().key());b.ingredients.getFirst().cooked=1.4;assertEquals("stir",r.problem(b).orElseThrow().key());b.stir();b.stir();assertTrue(r.matches(b));b.ingredients.getFirst().waterOnAdd=2;assertEquals("water_ratio",r.problem(b).orElseThrow().key());}
    @Test void noodlesMustBeRolledAndCutAndGreensPrepared(){var r=recipe("noodle_soup");var b=batch(CookingBatch.Method.BOIL,6);for(int i=0;i<2;i++)b.add("dough",CookingBatch.Cut.SHRED,1,false,false);b.add("cabbage",CookingBatch.Cut.SHRED,1,false,false);b.salt=1;ready(b);assertEquals("roll",r.problem(b).orElseThrow().key());b.ingredients.forEach(p->p.rolled=true);assertTrue(r.matches(b));b.ingredients.getFirst().cut=CookingBatch.Cut.WHOLE;assertEquals("cut",r.problem(b).orElseThrow().key());}
    @Test void dumplingsRequireWaterInBothCookingMethods(){for(var method:new CookingBatch.Method[]{CookingBatch.Method.BOIL,CookingBatch.Method.STEAM}){var b=batch(method,6);for(int i=0;i<2;i++)b.add("dumplings",CookingBatch.Cut.WHOLE,1,true,false);b.salt=1;ready(b);assertTrue(recipe("pork_dumplings").matches(b));b.water=0;assertEquals("water",recipe("pork_dumplings").problem(b).orElseThrow().key());}}
    @Test void bunsRequireFermentedDoughAndCoveredSteam(){var r=recipe("steamed_buns");var b=batch(CookingBatch.Method.STEAM,6);for(int i=0;i<2;i++)b.add("dough_fermented",CookingBatch.Cut.WHOLE,1,false,false);ready(b);assertEquals("cover",r.problem(b).orElseThrow().key());b.ingredients.forEach(p->p.coveredCookingSeconds=15);assertTrue(r.matches(b));b.ingredients.getFirst().id="dough";assertFalse(r.matches(b));}
    @Test void breadRequiresFermentationSugarAndActualOvenHeat(){var r=recipe("homestyle_bread");var b=batch(CookingBatch.Method.BAKE,0);for(int i=0;i<2;i++)b.add("dough_fermented",CookingBatch.Cut.WHOLE,1,false,false);ready(b);assertEquals("seasoning",r.problem(b).orElseThrow().key());b.sugar=1;assertEquals("oven",r.problem(b).orElseThrow().key());b.ovenSeconds=15;assertTrue(r.matches(b));b.ingredients.getFirst().id="dough";assertFalse(r.matches(b));}
    @Test void pieRequiresPreparedFilledPieAndOven(){var r=recipe("apple_pie");var b=batch(CookingBatch.Method.BAKE,0);b.add("pie",CookingBatch.Cut.WHOLE,1,false,false);ready(b);assertEquals("oven",r.problem(b).orElseThrow().key());b.ovenSeconds=15;assertTrue(r.matches(b));b.ingredients.getFirst().id="apple";assertFalse(r.matches(b));}
    @Test void soupServingRemovesAnEqualFractionOfWaterAndFreezesYield(){var b=batch(CookingBatch.Method.BOIL,6);b.add("tomato",CookingBatch.Cut.WHOLE,1,false,true);assertTrue(b.serve("soup",3));assertEquals(4,b.water,.0001);assertEquals(3,b.totalServings);assertTrue(b.serve("soup",99));assertEquals(2,b.water,.0001);assertTrue(b.serve("soup",99));assertEquals(0,b.water);assertFalse(b.serve("soup",99));}
    @Test void steamServingDoesNotRemoveReservoirWater(){var b=batch(CookingBatch.Method.STEAM,6);b.add("dumplings",CookingBatch.Cut.WHOLE,1,true,true);assertTrue(b.serve("dumplings",2));assertEquals(6,b.water);assertTrue(b.serve("dumplings",2));assertEquals(6,b.water);}
    @Test void oldPartialSaveCanRecoverBoundedVisibleYield(){var b=new CookingBatch();b.remainingServings=2;b.totalServings=0;b.ovenSeconds=Integer.MAX_VALUE;b.normalize();assertEquals(2,b.totalServings);assertEquals(100000,b.ovenSeconds);}
}
